out=[r[:] for r in g]
for (r0,r1,c0,c1) in regions:
    seeds=[(i,j,g[i][j]) for i in range(r0,r1+1) for j in range(c0,c1+1) if g[i][j]!=0]
    if not seeds: continue
    h,w=r1-r0+1,c1-c0+1
    ys=[s[0] for s in seeds]; xs=[s[1] for s in seeds]
    sy0,sy1,sx0,sx1=min(ys),max(ys),min(xs),max(xs)
    sh,sw=sy1-sy0+1,sx1-sx0+1
    oy=sy0-r0; ox=sx0-c0
    def blocks(off,size,length):
        if off==0: return list(range(0,length,size))
        elif off+size==length: return list(range(length-size,-1,-size))
        else: raise ValueError((off,size,length))
    rs=blocks(oy,sh,h); cs=blocks(ox,sw,w)
    assert h%sh==0 and w%sw==0, (h,sh,w,sw)
    for br in rs:
        for bc in cs:
            for i in range(sh):
                for j in range(sw):
                    out[r0+br+i][c0+bc+j]=g[sy0+i][sx0+j]
for r in out: print(' '.join(map(str,r)))
